H.background();
// Oxidation states: rules (O = -2, H = +1) force the central atom's number.
// Slider picks a sulfur compound; oxidation number of S is computed so the
// sum of oxidation numbers = overall charge (here neutral, sum = 0).
// Compounds: H2S, S8, SO2, SO3, H2SO4 with S oxidation states -2,0,+4,+6,+6.
const comps = [
  { f: "H2S",   parts: [["H", 2, +1], ["S", 1, null]], charge: 0 },
  { f: "S8",    parts: [["S", 8, null]],               charge: 0 },
  { f: "SO2",   parts: [["O", 2, -2], ["S", 1, null]], charge: 0 },
  { f: "SO3",   parts: [["O", 3, -2], ["S", 1, null]], charge: 0 },
  { f: "H2SO4", parts: [["H", 2, +1], ["O", 4, -2], ["S", 1, null]], charge: 0 }
];
const idx = Math.max(0, Math.min(comps.length - 1, Math.round(P.compound)));
const c = comps[idx];
// solve for the unknown (S) oxidation number
let known = 0, sCount = 1;
for (const p of c.parts) { if (p[2] !== null) known += p[1] * p[2]; else sCount = p[1]; }
const oxS = (c.charge - known) / sCount;
// layout boxes for each element, animate a highlight that sweeps the unknown
const cx = H.W / 2, cy = H.H / 2;
H.rect(cx - 220, cy - 70, 440, 140, { fill: H.colors.panel, stroke: H.colors.grid, width: 1, radius: 10 });
let x = cx - 170;
for (const p of c.parts) {
  const val = p[2] !== null ? p[2] : oxS;
  const col = p[2] === null ? H.colors.warn : H.colors.accent;
  const pulse = p[2] === null ? (0.5 + 0.5 * Math.sin(t * 3)) : 1;
  H.circle(x, cy + 8, 26, { fill: H.colors.bg, stroke: col, width: 2 + 2 * pulse });
  H.text(p[0] + (p[1] > 1 ? p[1] : ""), x, cy + 8, { color: H.colors.ink, size: 20, weight: 700, align: "center", baseline: "middle" });
  const sign = val >= 0 ? "+" : "";
  H.text(sign + val, x, cy - 40, { color: col, size: 16, weight: 700, align: "center" });
  x += 110;
}
H.text("Oxidation numbers: sum = overall charge", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("Rules: O = -2, H = +1; solve the rest. Compound: " + c.f, 24, 52, { color: H.colors.sub, size: 13 });
H.text("S in " + c.f + " = " + (oxS >= 0 ? "+" : "") + oxS + "  (sum of all = " + c.charge + ")", 24, 74, { color: H.colors.warn, size: 13 });
